def mcp__getComponentLink(workspace_id, session_id, url, sequence_index=None, **_extra):
    import json, os, datetime, re, time, uuid, urllib.parse, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0216000" if __import__("os").path.isdir("./environment_mix/0216000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _dur_ms():
        return int((time.time() - t0) * 1000)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = uuid.uuid4().bytes
        out = []
        for b in raw:
            out.append(alphabet[b % len(alphabet)])
            if len(out) >= 16:
                break
        return prefix + "".join(out)

    def _today_key(dt):
        return dt.date().isoformat()

    def _count_invocations_today(inv_rows, ws_id, dt):
        dkey = _today_key(dt)
        c = 0
        for r in inv_rows:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("tool_name") == "version_0.0.4-beta.11":
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and _today_key(ts) == dkey:
                c += 1
        return c

    def _append_invocation(inv_rows, workspace_id_val, session_id_val, request_params, resolved_file, resolved_layer,
                           http_status, result_status, error_code, error_message, produced_artifact_ids, resolved_root_path=None):
        inv_rows.append({
            "id": _new_id("mg_inv_"),
            "workspace_id": workspace_id_val,
            "session_id": session_id_val,
            "tool_name": "mcp__getComponentLink",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "resolved_external_file_id": resolved_file,
            "resolved_external_layer_id": resolved_layer,
            "resolved_root_path": resolved_root_path,
            "http_status": http_status,
            "duration_ms": _dur_ms(),
            "result_status": result_status,
            "error_code": error_code,
            "error_message": error_message,
            "produced_artifact_ids": produced_artifact_ids if isinstance(produced_artifact_ids, list) else [],
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^mg_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not isinstance(session_id, str) or not re.match(r"^mg_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id format.", field="session_id")
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required.", field="url")
    try:
        pu = urllib.parse.urlparse(url)
    except Exception:
        pu = None
    if not pu or pu.scheme not in ("http", "https") or not pu.netloc:
        return _err("VALIDATION_ERROR", "url must be a valid URI.", field="url")
    if sequence_index is not None:
        if not isinstance(sequence_index, int) or sequence_index < 0:
            return _err("VALIDATION_ERROR", "sequence_index must be an integer >= 0.", field="sequence_index")

    workspaces = _load("workspaces.json")
    sessions = _load("design_sessions.json")
    artifacts = _load("session_artifacts.json")
    invocations = _load("tool_invocations.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_invocation(invocations, workspace_id, session_id, {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                           None, None, None, "error", "NOT_FOUND", "Workspace not found.", [])
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # If workspace is deleted: refuse new tool invocations
    if ws.get("status") == "deleted":
        _append_invocation(invocations, workspace_id, session_id, {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                           None, None, None, "error", "UNAUTHORIZED", "Workspace is deleted; new tool invocations are not allowed.", [])
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Workspace is deleted; new tool invocations are not allowed.", workspace_id=workspace_id)

    # Resolve session: MUST exist and belong to workspace; if not, NOT_FOUND (not UNAUTHORIZED)
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        _append_invocation(invocations, workspace_id, session_id, {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                           None, None, None, "error", "NOT_FOUND", "Session not found in workspace.", [])
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Session not found in workspace.", workspace_id=workspace_id, session_id=session_id)

    # Enforce per-workspace fetch quota (non-version tool)
    quota = ws.get("quota_fetches_per_day")
    if not isinstance(quota, int) or quota < 0:
        quota = 0
    used = _count_invocations_today(invocations, workspace_id, now_dt)
    if used >= quota:
        _append_invocation(invocations, workspace_id, session_id, {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                           sess.get("external_file_id"), sess.get("external_layer_id"), 429, "rate_limited", "QUOTA_EXCEEDED",
                           "Workspace fetch quota exceeded; tool invocation returned rate_limited.", [])
        _save("tool_invocations.json", invocations)
        return _err("QUOTA_EXCEEDED", "Workspace fetch quota exceeded.", workspace_id=workspace_id, quota_fetches_per_day=quota)

    # Update session last_activity_at (read/write side effect)
    sess["last_activity_at"] = now_iso
    sess["updated_at"] = now_iso

    # Create/update component_doc artifact unique by (session_id, external_url)
    existing = None
    for a in artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("session_id") == session_id and a.get("artifact_type") == "component_doc" and a.get("external_url") == url:
            existing = a
            break

    # If existing is expired, cannot transition back to ready: create a new row
    if existing and existing.get("status") == "expired":
        existing = None

    produced_ids = []
    # "Fetch" offline: we store minimal doc stub as content_text; must satisfy constraint: at least one content field non-null
    doc_text = f"Component documentation fetched for {url}\n(offline datastore mode)"
    sha = hashlib.sha256(doc_text.encode("utf-8")).hexdigest()

    if existing:
        # allowed transitions: pending->ready/error; ready can't go to ready (no transition); but we can treat as idempotent
        # If already ready with same sha, keep as-is (idempotent) but still record invocation
        if existing.get("status") == "ready" and existing.get("content_sha256") == sha:
            if sequence_index is not None:
                existing["sequence_index"] = sequence_index
            existing["updated_at"] = now_iso
            produced_ids = [existing.get("id")]
            _append_invocation(invocations, workspace_id, session_id,
                               {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                               sess.get("external_file_id"), sess.get("external_layer_id"), 200, "ok", None, None, produced_ids)
            _save("design_sessions.json", sessions)
            _save("session_artifacts.json", artifacts)
            _save("tool_invocations.json", invocations)
            return {"artifact": existing, "session_id": session_id}

        # If currently ready but content differs, create new row (ready cannot transition except to expired per lifecycle)
        if existing.get("status") == "ready":
            existing = None
        else:
            # pending or error: can transition to ready
            existing["status"] = "ready"
            existing["source_tool"] = "mcp__getComponentLink"
            existing["external_url"] = url
            if sequence_index is not None:
                existing["sequence_index"] = sequence_index
            existing["content_text"] = doc_text
            existing["content_json"] = None
            existing["content_markdown"] = None
            existing["content_sha256"] = sha
            existing["error_code"] = None
            existing["error_message"] = None
            existing["fetched_at"] = now_iso
            existing["updated_at"] = now_iso
            produced_ids = [existing.get("id")]
            _append_invocation(invocations, workspace_id, session_id,
                               {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                               sess.get("external_file_id"), sess.get("external_layer_id"), 200, "ok", None, None, produced_ids)
            _save("design_sessions.json", sessions)
            _save("session_artifacts.json", artifacts)
            _save("tool_invocations.json", invocations)
            return {"artifact": existing, "session_id": session_id}

    # Create new
    art = {
        "id": _new_id("mg_art_"),
        "session_id": session_id,
        "artifact_type": "component_doc",
        "status": "ready",
        "source_tool": "mcp__getComponentLink",
        "external_url": url,
        "sequence_index": sequence_index if sequence_index is not None else None,
        "root_path": None,
        "content_json": None,
        "content_markdown": None,
        "content_text": doc_text,
        "content_sha256": sha,
        "error_code": None,
        "error_message": None,
        "fetched_at": now_iso,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    artifacts.append(art)
    produced_ids = [art["id"]]
    _append_invocation(invocations, workspace_id, session_id,
                       {"workspace_id": workspace_id, "session_id": session_id, "url": url, "sequence_index": sequence_index},
                       sess.get("external_file_id"), sess.get("external_layer_id"), 200, "ok", None, None, produced_ids)
    _save("design_sessions.json", sessions)
    _save("session_artifacts.json", artifacts)
    _save("tool_invocations.json", invocations)
    return {"artifact": art, "session_id": session_id}

def mg__whoami(workspace_id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0216000" if __import__("os").path.isdir("./environment_mix/0216000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        x = ts
        out = []
        while x > 0 and len(out) < 13:
            out.append(_ALPH[x % 32])
            x //= 32
        while len(out) < 13:
            out.append(_ALPH[int(time.time_ns()) % 32])
        return prefix + "".join(reversed(out))

    def _log(invocations, workspace_id, result_status, error_code=None, error_message=None):
        dur = int((time.time() - t0) * 1000)
        inv = {
            "id": _new_id("mg_inv_"),
            "workspace_id": workspace_id,
            "session_id": None,
            "tool_name": "version_0.0.4-beta.11",  # whoami isn't in vendor tool list; record as version tool to keep enum valid
            "request_params": {"workspace_id": workspace_id},
            "resolved_external_file_id": None,
            "resolved_external_layer_id": None,
            "resolved_root_path": None,
            "http_status": None,
            "duration_ms": dur,
            "result_status": result_status,
            "error_code": error_code,
            "error_message": error_message,
            "produced_artifact_ids": [],
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv)

    if not (isinstance(workspace_id, str) and re.match(r"^mg_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id) is not None):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")

    workspaces = _load("workspaces.json")
    invocations = _load("tool_invocations.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        # can't log with a missing workspace reliably per FK; still return
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Ambient auth: if workspace exists, allow; otherwise forbidden isn't reachable in this datastore model.
    # Compute quota consumption for today.
    def _day_key(ts):
        return ts[:10] if isinstance(ts, str) and len(ts) >= 10 else None
    today = now[:10]

    used_sessions = 0
    sessions = _load("design_sessions.json")
    for s in sessions:
        if s.get("workspace_id") == workspace_id and _day_key(s.get("created_at")) == today:
            used_sessions += 1

    used_fetches = 0
    for inv in invocations:
        if inv.get("workspace_id") == workspace_id and inv.get("tool_name") != "version_0.0.4-beta.11":
            if _day_key(inv.get("created_at")) == today:
                used_fetches += 1

    _log(invocations, workspace_id, "ok")
    _save("tool_invocations.json", invocations)

    return {
        "subject": ws.get("owner_subject"),
        "scopes": ["workspace:read", "workspace:write", "sessions:read", "tools:invoke"],
        "workspace": {"id": ws.get("id"), "name": ws.get("name"), "status": ws.get("status")},
        "quota": {
            "date_utc": today,
            "sessions": {"used": used_sessions, "limit": ws.get("quota_sessions_per_day")},
            "fetches": {"used": used_fetches, "limit": ws.get("quota_fetches_per_day")}
        }
    }

def mg__listDesignSessions(workspace_id, design_file_id=None, external_file_id=None, external_layer_id=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0216000" if __import__("os").path.isdir("./environment_mix/0216000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        x = ts
        out = []
        while x > 0 and len(out) < 13:
            out.append(_ALPH[x % 32])
            x //= 32
        while len(out) < 13:
            out.append(_ALPH[int(time.time_ns()) % 32])
        return prefix + "".join(reversed(out))

    def _log(invocations, workspace_id, result_status, error_code=None, error_message=None):
        dur = int((time.time() - t0) * 1000)
        invocations.append({
            "id": _new_id("mg_inv_"),
            "workspace_id": workspace_id,
            "session_id": None,
            "tool_name": "version_0.0.4-beta.11",  # listDesignSessions not in enum; log as version tool
            "request_params": {
                "workspace_id": workspace_id,
                "design_file_id": design_file_id,
                "external_file_id": external_file_id,
                "external_layer_id": external_layer_id,
                "status": status,
                "limit": limit,
                "cursor": cursor
            },
            "resolved_external_file_id": None,
            "resolved_external_layer_id": None,
            "resolved_root_path": None,
            "http_status": None,
            "duration_ms": dur,
            "result_status": result_status,
            "error_code": error_code,
            "error_message": error_message,
            "produced_artifact_ids": [],
            "created_at": now,
            "updated_at": now,
        })

    # Validate inputs
    if not (isinstance(workspace_id, str) and re.match(r"^mg_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id) is not None):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if design_file_id is not None and not (isinstance(design_file_id, str) and re.match(r"^mg_df_[0-9A-HJKMNP-TV-Z]{10,}$", design_file_id) is not None):
        return _err("VALIDATION_ERROR", "Invalid design_file_id format.", field="design_file_id")
    if external_file_id is not None and (not isinstance(external_file_id, str) or len(external_file_id) < 1):
        return _err("VALIDATION_ERROR", "external_file_id must be a non-empty string.", field="external_file_id")
    if external_layer_id is not None and (not isinstance(external_layer_id, str) or len(external_layer_id) < 1):
        return _err("VALIDATION_ERROR", "external_layer_id must be a non-empty string.", field="external_layer_id")
    if status is not None and status not in ("active", "completed", "failed", "expired"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")

    workspaces = _load("workspaces.json")
    sessions = _load("design_sessions.json")
    invocations = _load("tool_invocations.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Pagination cursor: base64 of {"last_activity_at": "...", "id": "..."}
    start_after = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "last_activity_at" not in obj or "id" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            start_after = (obj.get("last_activity_at"), obj.get("id"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Filter and sort
    rows = []
    for s in sessions:
        if s.get("workspace_id") != workspace_id:
            continue
        if design_file_id is not None and s.get("design_file_id") != design_file_id:
            continue
        if external_file_id is not None and s.get("external_file_id") != external_file_id:
            continue
        if external_layer_id is not None and s.get("external_layer_id") != external_layer_id:
            continue
        if status is not None and s.get("status") != status:
            continue
        rows.append(s)

    def _key(s):
        # most recent activity desc, then id desc
        return (s.get("last_activity_at") or "", s.get("id") or "")
    rows.sort(key=_key, reverse=True)

    if start_after is not None:
        la, sid = start_after
        filtered = []
        for s in rows:
            k = (s.get("last_activity_at") or "", s.get("id") or "")
            # since sorted desc: keep those strictly less than cursor key
            if k < (la or "", sid or ""):
                filtered.append(s)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = len(rows) > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = json.dumps({"last_activity_at": last.get("last_activity_at"), "id": last.get("id")}, ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log(invocations, workspace_id, "ok")
    _save("tool_invocations.json", invocations)

    return {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

