    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_invocation(invocations, workspace_id, session_id, "error", "NOT_FOUND", "Workspace not found.")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        # This MUST be NOT_FOUND (not UNAUTHORIZED) when workspace mismatch
        _append_invocation(invocations, workspace_id, session_id, "error", "NOT_FOUND", "Session not found in workspace.")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Session not found in workspace.", workspace_id=workspace_id, session_id=session_id)

    # Retention behavior for deleted workspaces: allow reads (as per rule), so no refusal here.
    _append_invocation(invocations, workspace_id, session_id, "ok", None, None)
    _save("tool_invocations.json", invocations)

    return {"session": sess}

def mg__createDesignSession(workspace_id, fileId, layerId, design_file_id=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0216000" if __import__("os").path.isdir("./environment_mix/0216000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- validate inputs
    ws_pat = re.compile(r"^mg_ws_[0-9A-HJKMNP-TV-Z]{10,}$")
    df_pat = re.compile(r"^mg_df_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(fileId, str) or len(fileId) < 1:
        return _err("VALIDATION_ERROR", "fileId must be a non-empty string.")
    if not isinstance(layerId, str) or len(layerId) < 1:
        return _err("VALIDATION_ERROR", "layerId must be a non-empty string.")
    if design_file_id is not None:
        if not isinstance(design_file_id, str) or not df_pat.match(design_file_id):
            return _err("VALIDATION_ERROR", "Invalid design_file_id.")

    workspaces = _load("workspaces.json")
    design_files = _load("design_files.json")
    design_sessions = _load("design_sessions.json")
    invocations = _load("tool_invocations.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # "FORBIDDEN" mentioned in tool description, but contract restricts error codes;
    # use UNAUTHORIZED for inaccessible/deleted.
    if ws.get("status") == "deleted":
        # record invocation attempt as error (not rate_limited)
        inv_id = "mg_inv_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]
        inv = {
            "id": inv_id,
            "workspace_id": workspace_id,
            "session_id": None,
            "tool_name": "mcp__getDsl",  # closest available; this endpoint is session creation (no schema enum). Avoid inventing new tool_name.
            "request_params": {"workspace_id": workspace_id, "fileId": fileId, "layerId": layerId, "design_file_id": design_file_id},
            "resolved_external_file_id": fileId,
            "resolved_external_layer_id": layerId,
            "resolved_root_path": None,
            "http_status": None,
            "duration_ms": int((time.time() - t0) * 1000),
            "result_status": "error",
            "error_code": "UNAUTHORIZED",
            "error_message": "Workspace is deleted.",
            "produced_artifact_ids": [],
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Workspace is deleted and cannot create new sessions.", workspace_id=workspace_id)

    # Resolve or validate design_file_id against workspace and fileId
    df_row = None
    if design_file_id is not None:
        df_row = next((d for d in design_files if d.get("id") == design_file_id), None)
        if not df_row:
            return _err("NOT_FOUND", "design_file_id not found.", design_file_id=design_file_id)
        if df_row.get("workspace_id") != workspace_id:
            return _err("UNAUTHORIZED", "design_file_id does not belong to workspace.", design_file_id=design_file_id, workspace_id=workspace_id)
        if df_row.get("external_file_id") != fileId:
            return _err("CONFLICT", "design_file_id external_file_id does not match provided fileId.",
                        design_file_id=design_file_id, fileId=fileId, external_file_id=df_row.get("external_file_id"))
    else:
        # find existing active/archived file reference for workspace+fileId; else create a new one
        df_row = next((d for d in design_files
                       if d.get("workspace_id") == workspace_id and d.get("external_file_id") == fileId), None)
        if df_row is None:
            df_id = "mg_df_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]
            df_row = {
                "id": df_id,
                "workspace_id": workspace_id,
                "external_file_id": fileId,
                "name": None,
                "status": "active",
                "last_synced_at": None,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            design_files.append(df_row)
            _save("design_files.json", design_files)
        else:
            # If revoked, cannot create new sessions because file reference is revoked (treat as unauthorized)
            if df_row.get("status") == "revoked":
                return _err("UNAUTHORIZED", "Design file reference is revoked.", design_file_id=df_row.get("id"))

    # ---- enforce quota_sessions_per_day for newly created design_sessions
    # Count sessions created today in UTC for this workspace
    def _day_start(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)
    day0 = _day_start(now)
    day0_iso = day0.isoformat() + "Z"
    created_today = 0
    for s in design_sessions:
        if s.get("workspace_id") != workspace_id:
            continue
        ca = s.get("created_at")
        if isinstance(ca, str) and ca >= day0_iso:
            created_today += 1

    quota = ws.get("quota_sessions_per_day")
    if not isinstance(quota, int) or quota < 0:
        return _err("VALIDATION_ERROR", "Workspace quota_sessions_per_day is invalid.", quota_sessions_per_day=quota)

    if created_today >= quota:
        return _err("QUOTA_EXCEEDED", "Daily session quota exceeded for workspace.",
                    quota_sessions_per_day=quota, sessions_created_today=created_today)

    # ---- create new session (must not reuse expired session)
    sess_id = "mg_sess_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]
    sess = {
        "id": sess_id,
        "workspace_id": workspace_id,
        "design_file_id": df_row.get("id"),
        "external_file_id": fileId,
        "external_layer_id": layerId,
        "status": "active",
        "last_activity_at": now_iso,
        "expires_at": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    design_sessions.append(sess)
    _save("design_sessions.json", design_sessions)

    # record invocation-like audit row (closest tool enum doesn't include session creation; use version tool? would be wrong.
    # We'll record under version tool would violate rule #10. Instead use mcp__getDsl as a proxy audit record.
    inv_id = "mg_inv_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]
    inv = {
        "id": inv_id,
        "workspace_id": workspace_id,
        "session_id": sess_id,
        "tool_name": "mcp__getDsl",
        "request_params": {"workspace_id": workspace_id, "fileId": fileId, "layerId": layerId, "design_file_id": design_file_id},
        "resolved_external_file_id": fileId,
        "resolved_external_layer_id": layerId,
        "resolved_root_path": None,
        "http_status": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "result_status": "ok",
        "error_code": None,
        "error_message": None,
        "produced_artifact_ids": [],
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {
        "session": sess,
        "design_file": df_row,
    }

def mg__listSessionArtifacts(workspace_id, session_id, artifact_type=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0216000" if __import__("os").path.isdir("./environment_mix/0216000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _dur_ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        import uuid
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = uuid.uuid4().bytes
        out = []
        for b in raw:
            out.append(alphabet[b % len(alphabet)])
            if len(out) >= 16:
                break
        return prefix + "".join(out)

    def _append_invocation(inv_rows, workspace_id_val, session_id_val, result_status, error_code=None, error_message=None):
        inv_rows.append({
            "id": _new_id("mg_inv_"),
            "workspace_id": workspace_id_val,
            "session_id": session_id_val,
            "tool_name": "version_0.0.4-beta.11",  # read logging bucket
            "request_params": {
                "workspace_id": workspace_id_val,
                "session_id": session_id_val,
                "artifact_type": artifact_type,
                "status": status,
                "limit": limit,
                "cursor": cursor,
            },
            "resolved_external_file_id": None,
            "resolved_external_layer_id": None,
            "resolved_root_path": None,
            "http_status": None,
            "duration_ms": _dur_ms(),
            "result_status": result_status,
            "error_code": error_code,
            "error_message": error_message,
            "produced_artifact_ids": [],
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^mg_ws_[0-9A-HJKMNP-TV-Z]{10,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")
    if not isinstance(session_id, str) or not re.match(r"^mg_sess_[0-9A-HJKMNP-TV-Z]{10,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id.", field="session_id")
    if artifact_type is not None and artifact_type not in ("dsl", "meta_rules_md", "meta_results_json", "component_doc", "generator_workflow"):
        return _err("VALIDATION_ERROR", "Invalid artifact_type.", field="artifact_type")
    if status is not None and status not in ("pending", "ready", "error", "expired"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")

    workspaces = _load("workspaces.json")
    sessions = _load("design_sessions.json")
    artifacts = _load("session_artifacts.json")
    invocations = _load("tool_invocations.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_invocation(invocations, workspace_id, session_id, "error", "NOT_FOUND", "Workspace not found.")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id and s.get("workspace_id") == workspace_id), None)
    if not sess:
        _append_invocation(invocations, workspace_id, session_id, "error", "NOT_FOUND", "Session not found in workspace.")
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Session not found in workspace.", workspace_id=workspace_id, session_id=session_id)

    # Pagination: cursor is base64 of last_seen_artifact_id; ordering by created_at then id for stability
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1]) if s.endswith("Z") else datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    rows = [a for a in artifacts if isinstance(a, dict) and a.get("session_id") == session_id]
    if artifact_type is not None:
        rows = [a for a in rows if a.get("artifact_type") == artifact_type]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]

    rows.sort(key=lambda r: ((_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)), r.get("id") or ""))

    start_idx = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
        except Exception:
            decoded = None
        if decoded:
            for i, r in enumerate(rows):
                if r.get("id") == decoded:
                    start_idx = i + 1
                    break

    page = rows[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(rows)
    next_cursor = None
    if has_more and page:
        next_cursor = base64.urlsafe_b64encode((page[-1].get("id") or "").encode("utf-8")).decode("utf-8")

    _append_invocation(invocations, workspace_id, session_id, "ok", None, None)
    _save("tool_invocations.json", invocations)

    return {
        "artifacts": page,
        "pagination": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def mg__updateWorkspace(workspace_id, name=None, default_root_path=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0216000" if __import__("os").path.isdir("./environment_mix/0216000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    ws_pat = re.compile(r"^mg_ws_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(workspace_id, str) or not ws_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    if name is not None:
        if not isinstance(name, str) or len(name) < 1 or len(name) > 200:
            return _err("VALIDATION_ERROR", "name must be a non-empty string up to 200 characters.")
    if default_root_path is not None:
        if not isinstance(default_root_path, str) or len(default_root_path) < 1:
            return _err("VALIDATION_ERROR", "default_root_path must be a non-empty string.")
        if not default_root_path.startswith("/"):
            return _err("VALIDATION_ERROR", "default_root_path must be an absolute path starting with '/'.")
        if "\x00" in default_root_path:
            return _err("VALIDATION_ERROR", "default_root_path must not contain null bytes.")
    if status is not None:
        if not isinstance(status, str) or status not in {"active", "suspended", "deleted"}:
            return _err("VALIDATION_ERROR", "Invalid status value.")

    workspaces = _load("workspaces.json")
    invocations = _load("tool_invocations.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # unique(owner_subject, name)
    if name is not None:
        for w in workspaces:
            if w.get("id") != workspace_id and w.get("owner_subject") == ws.get("owner_subject") and w.get("name") == name:
                return _err("CONFLICT", "Workspace name already exists for this owner_subject.", owner_subject=ws.get("owner_subject"), name=name)

    # lifecycle transition validation
    if status is not None:
        cur = ws.get("status")
        transitions = {
            "active": {"suspended", "deleted"},
            "suspended": {"active", "deleted"},
            "deleted": set(),
        }
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "Workspace has invalid current status.", current_status=cur)
        if status != cur and status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "Illegal workspace status transition.", from_status=cur, to_status=status)

    # apply updates
    changed = False
    if name is not None and ws.get("name") != name:
        ws["name"] = name
        changed = True
    if default_root_path is not None and ws.get("default_root_path") != default_root_path:
        ws["default_root_path"] = default_root_path
        changed = True
    if status is not None and ws.get("status") != status:
        ws["status"] = status
        changed = True

    if not changed:
        # idempotent update: still record invocation, but return the current workspace
        inv_id = "mg_inv_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]
        inv = {
            "id": inv_id,
            "workspace_id": workspace_id,
            "session_id": None,
            "tool_name": "version_0.0.4-beta.11",
            "request_params": {"workspace_id": workspace_id, "name": name, "default_root_path": default_root_path, "status": status},
            "resolved_external_file_id": None,
            "resolved_external_layer_id": None,
            "resolved_root_path": default_root_path if default_root_path is not None else ws.get("default_root_path"),
            "http_status": None,
            "duration_ms": int((time.time() - t0) * 1000),
            "result_status": "ok",
            "error_code": None,
            "error_message": None,
            "produced_artifact_ids": [],
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return {"workspace": ws, "updated": False}

    ws["updated_at"] = now_iso
    _save("workspaces.json", workspaces)

    # record invocation
    inv_id = "mg_inv_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:16]
    inv = {
        "id": inv_id,
        "workspace_id": workspace_id,
        "session_id": None,
        "tool_name": "version_0.0.4-beta.11",
        "request_params": {"workspace_id": workspace_id, "name": name, "default_root_path": default_root_path, "status": status},
        "resolved_external_file_id": None,
        "resolved_external_layer_id": None,
        "resolved_root_path": default_root_path if default_root_path is not None else ws.get("default_root_path"),
        "http_status": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "result_status": "ok",
        "error_code": None,
        "error_message": None,
        "produced_artifact_ids": [],
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {"workspace": ws, "updated": True}
